//! 🧮️ Original table rows and recursive cells share one retained relational workspace.
use super::{SemioTableSnapshot,SemioTableColumn,SemioTableRow,SemioTableCellKind,identity,VALUES};
use crate::standards::v1::subsets::value::io::sqlite::snapshot::{ValueForestStorage,reconstruct_value_forest_into};
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,artifact::{RowIndex,RowIndexStorage,reconstruct_text_into},transfer::{SchemaValidationStorage,validate_database_into,validate_component_into,reserve}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
#[derive(semio_framework_value::RetireOwned)]
struct Prefix{snapshot:Option<SemioTableSnapshot>,validation:SchemaValidationStorage,indexes:[RowIndexStorage;3],orders:[Vec<usize>;3],roots:Vec<i64>,widths:Vec<usize>,forest:ValueForestStorage}
fn empty()->Prefix{Prefix{snapshot:Some(super::native_decoding::empty()),validation:SchemaValidationStorage::empty(),indexes:std::array::from_fn(|_|RowIndexStorage::empty()),orders:std::array::from_fn(|_|Vec::new()),roots:Vec::new(),widths:Vec::new(),forest:ValueForestStorage::empty()}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
pub(super)fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>,declared:&str)->Result<SemioTableSnapshot,ValueError>{crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding::workspace::reconstruct_projected(control,empty,|prefix,control|{
 let phase=SqliteSnapshotPhase::ReconstructSnapshot;control.check_database(database,phase)?;validate_database_into(&mut prefix.validation,database,declared,phase,control)?;validate_component_into(&mut prefix.validation,database,SemioTableSnapshot::SQLITE_SCHEMA,phase,control)?;let document=database.table("semio_table_document")?.single_row()?;identity(document,2)?;if document.rowid!=1{return Err(invalid("invalid Semio table document identifier"))}let [column_index,row_index,cell_index]=&mut prefix.indexes;let [column_order,row_order,cell_order]=&mut prefix.orders;let columns=RowIndex::new(column_index,database,"semio_table_column",5,&[],control,"invalid Semio table column identity")?;let rows=RowIndex::new(row_index,database,"semio_table_row",3,&[],control,"invalid Semio table row identity")?;let cells=RowIndex::new(cell_index,database,"semio_table_cell",4,&[],control,"invalid Semio table cell identity")?;columns.ordered_into(column_order,2,control,"Semio table column ordinals require contiguous occurrences")?;rows.ordered_into(row_order,2,control,"Semio table row ordinals require contiguous occurrences")?;
 for source in [&columns,&rows]{for(count,&index)in source.indices().iter().enumerate(){if source.row(index)?.integer(1)?!=1{return Err(invalid("invalid Semio table document parent"))}control.checkpoint(phase,count+1,source.len())?;}}for(count,&index)in cells.indices().iter().enumerate(){if rows.get(cells.row(index)?.integer(1)?,control)?.is_none(){return Err(invalid("dangling Semio table row"))}control.checkpoint(phase,count+1,cells.len())?;}cells.grouped_by_into(cell_order,2,control,"Semio table cell ordinals require contiguous occurrences",|row|Ok((0,Some(row.integer(1)?))))?;
 let snapshot=prefix.snapshot.as_mut().unwrap();snapshot.columns=reserve(column_order.len(),control)?;for(count,&index)in column_order.iter().enumerate(){let row=columns.row(index)?;let kind=match row.text(4)?{"null"=>SemioTableCellKind::Null,"bool"=>SemioTableCellKind::Bool,"int"=>SemioTableCellKind::Int,"float"=>SemioTableCellKind::Float,"str"=>SemioTableCellKind::Str,"bytes"=>SemioTableCellKind::Bytes,_=>return Err(invalid("unknown Semio table column kind"))};snapshot.columns.push(SemioTableColumn{name:String::new(),kind});reconstruct_text_into(&mut snapshot.columns.last_mut().unwrap().name,control,row.text(3)?)?;control.checkpoint(phase,count+1,column_order.len())?;}
 prefix.roots=reserve(cells.len(),control)?;prefix.widths=reserve(rows.len(),control)?;for &index in row_order.iter(){let row=rows.row(index)?;let range=cells.range_by(cell_order,(0,Some(row.rowid)),control,|row|Ok((0,Some(row.integer(1)?))))?;prefix.widths.push(range.len());for position in range{prefix.roots.push(cells.row(cell_order[position])?.integer(3)?);control.checkpoint(phase,prefix.roots.len(),cells.len())?;}}if prefix.roots.len()!=cells.len(){return Err(invalid("unconsumed Semio table cell"))}reconstruct_value_forest_into(&mut prefix.forest,database,VALUES,&prefix.roots,None,control)?;snapshot.rows=reserve(prefix.widths.len(),control)?;let mut completed=0;for &width in &prefix.widths{snapshot.rows.push(SemioTableRow{cells:Vec::new()});let row=snapshot.rows.last_mut().unwrap();row.cells=reserve(width,control)?;for _ in 0..width{row.cells.push(prefix.forest.take_root(completed)?);completed+=1;control.checkpoint(phase,completed,cells.len())?;}}if !prefix.forest.roots_consumed(){return Err(invalid("unconsumed Semio table cell value"))}reconstruct_text_into(&mut snapshot.schema,control,document.text(1)?)?;control.checkpoint(phase,completed,completed)
},|prefix|prefix.snapshot.take().unwrap())}
